import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib
matplotlib.use('Agg')
import base64
from io import BytesIO
import json

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Load charts
with open('/app/output/charts.json', 'r') as f:
    charts = json.load(f)

# Calculate all KPIs
total_listings = len(df)
unique_brands = df['brand'].unique()
unique_countries = df['Country'].unique()
unique_sellers = df['Seller_ID'].nunique()

# Median by brand
median_by_brand = df.groupby('brand')['price'].median().sort_values(ascending=False)

# Geographic spread
country_brand_median = df.groupby(['Country', 'brand'])['price'].median().unstack()
geo_spread = country_brand_median.max() - country_brand_median.min()

# Case size correlation
df_case = df.dropna(subset=['Case_Size_mm'])
case_corr = df_case['Case_Size_mm'].corr(df_case['price'])

# Power seller concentration
seller_counts = df.groupby('Seller_ID').size().reset_index(name='count')
total_sellers = len(seller_counts)
top_5_percent_cutoff = int(np.ceil(total_sellers * 0.05))
top_sellers = seller_counts.nlargest(top_5_percent_cutoff, 'count')
top_seller_ids = top_sellers['Seller_ID'].tolist()
power_seller_listings = df[df['Seller_ID'].isin(top_seller_ids)]
power_seller_concentration = len(power_seller_listings) / len(df) * 100

# New vs Used premium
new_used = df[df['condition'].isin(['New', 'Used'])]
new_used_avg = new_used.groupby(['brand', 'condition'])['price'].mean().unstack()
new_used_premium = ((new_used_avg['New'] - new_used_avg['Used']) / new_used_avg['Used'] * 100)

# Brand stats
brand_stats = df.groupby('brand')['price'].agg(['mean', 'median', 'std', 'min', 'max', 'count'])

# Seller analysis
high_volume_sellers = df[df['Seller_ID'].isin(top_seller_ids)]
low_volume_sellers = df[~df['Seller_ID'].isin(top_seller_ids)]
power_seller_avg_price = high_volume_sellers['price'].mean()
regular_seller_avg_price = low_volume_sellers['price'].mean()

# Geographic data for heatmap
country_brand_pct = ((country_brand_median - country_brand_median.mean()) / country_brand_median.mean() * 100)

# Condition distribution
condition_brand = pd.crosstab(df['brand'], df['condition'])

# Power seller brand distribution
power_seller_brand = high_volume_sellers['brand'].value_counts(normalize=True) * 100
regular_seller_brand = low_volume_sellers['brand'].value_counts(normalize=True) * 100

# Generate HTML heatmap
def generate_geo_heatmap_html():
    html = '<table class="geo-heatmap">\n'
    html += '<tr><th>Country</th><th>Apple</th><th>Garmin</th><th>Samsung</th></tr>\n'

    top_countries_list = ['United States', 'United Kingdom', 'Japan', 'South Korea', 'Italy', 'Canada', 'Germany', 'Australia', 'Hong Kong', 'Malaysia']

    for country in top_countries_list:
        if country in country_brand_pct.index:
            apple_val = country_brand_pct.loc[country, 'Apple'] if 'Apple' in country_brand_pct.columns and pd.notna(country_brand_pct.loc[country, 'Apple']) else 0
            garmin_val = country_brand_pct.loc[country, 'Garmin'] if 'Garmin' in country_brand_pct.columns and pd.notna(country_brand_pct.loc[country, 'Garmin']) else 0
            samsung_val = country_brand_pct.loc[country, 'Samsung'] if 'Samsung' in country_brand_pct.columns and pd.notna(country_brand_pct.loc[country, 'Samsung']) else 0

            html += f'<tr><td>{country}</td>'
            html += f'<td class="heat-cell" style="background-color: {"#d4edda" if apple_val > 0 else "#f8d7da"}">{apple_val:+.1f}%</td>'
            html += f'<td class="heat-cell" style="background-color: {"#d4edda" if garmin_val > 0 else "#f8d7da"}">{garmin_val:+.1f}%</td>'
            html += f'<td class="heat-cell" style="background-color: {"#d4edda" if samsung_val > 0 else "#f8d7da"}">{samsung_val:+.1f}%</td>'
            html += '</tr>\n'

    html += '</table>'
    return html

